"""Shared test fixtures.

**Nothing here is real data.** Every row is generated by ``make_synthetic_raw``
from a seeded RNG, and every identifier is prefixed ``DEMO-`` so a synthetic
row can never be mistaken for an IBM Telco observation in a log, a screenshot
or a bug report. The test suite therefore runs in CI with no dataset download
and no network access.

The generator reproduces the dataset's *structure*, not its statistics: the
same columns, the same category vocabularies, the same "No internet service"
dependency between add-ons and ``InternetService``, and the same
blank-``TotalCharges``-at-zero-tenure quirk. A churn signal is injected through
contract type and tenure so that a model trained on the fixture learns
something and the end-to-end path is genuinely exercised - but the coefficients
it learns are meaningless and no test asserts a performance number.
"""

from __future__ import annotations

import hashlib
from pathlib import Path

import numpy as np
import pandas as pd
import pytest

from churnsense.config import Config, load_config
from churnsense.data import schema

FIXTURE_DIR = Path(__file__).parent / "fixtures"
DEMO_CSV = FIXTURE_DIR / "demo_customers.csv"


def make_synthetic_raw(n: int = 400, seed: int = 0) -> pd.DataFrame:
    """Build a raw-shaped frame: all strings, same vocabularies as the real file."""
    rng = np.random.default_rng(seed)

    def pick(options: tuple[str, ...], p: list[float] | None = None) -> np.ndarray:
        return rng.choice(options, size=n, p=p)

    contract = pick(("Month-to-month", "One year", "Two year"), [0.55, 0.21, 0.24])
    tenure = np.where(
        contract == "Month-to-month",
        rng.integers(0, 40, n),
        rng.integers(12, 73, n),
    )
    # A handful of day-one customers, mirroring the real file's tenure == 0 rows.
    tenure[rng.choice(n, size=max(2, n // 100), replace=False)] = 0

    phone = pick(("Yes", "No"), [0.9, 0.1])
    internet = pick(("DSL", "Fiber optic", "No"), [0.34, 0.44, 0.22])
    has_internet = internet != "No"
    monthly = np.where(has_internet, rng.uniform(45, 119, n), rng.uniform(18, 40, n)).round(2)

    def addon() -> np.ndarray:
        """Add-ons are only purchasable with internet - mirror that dependency."""
        return np.where(has_internet, pick(("Yes", "No"), [0.4, 0.6]), "No internet service")

    # Churn probability driven by contract and tenure so the signal is learnable.
    base = np.where(
        contract == "Month-to-month", 0.45, np.where(contract == "One year", 0.14, 0.05)
    )
    churn_p = np.clip(base - tenure / 240, 0.02, 0.95)

    # Built as text up front rather than written over a float column afterwards:
    # reproduces the real file's blank-at-zero-tenure quirk without pandas having
    # to widen a float64 column to hold a space.
    total_charges = np.where(tenure == 0, " ", (tenure * monthly).round(2).astype(str))

    frame = pd.DataFrame(
        {
            schema.ID_COLUMN: [f"DEMO-{i:05d}" for i in range(n)],
            "gender": pick(("Female", "Male")),
            "SeniorCitizen": pick(("0", "1"), [0.84, 0.16]),
            "Partner": pick(("Yes", "No")),
            "Dependents": pick(("Yes", "No"), [0.3, 0.7]),
            "tenure": tenure,
            "PhoneService": phone,
            "MultipleLines": np.where(phone == "Yes", pick(("Yes", "No")), "No phone service"),
            "InternetService": internet,
            "OnlineSecurity": addon(),
            "OnlineBackup": addon(),
            "DeviceProtection": addon(),
            "TechSupport": addon(),
            "StreamingTV": addon(),
            "StreamingMovies": addon(),
            "Contract": contract,
            "PaperlessBilling": pick(("Yes", "No")),
            "PaymentMethod": pick(
                (
                    "Bank transfer (automatic)",
                    "Credit card (automatic)",
                    "Electronic check",
                    "Mailed check",
                )
            ),
            "MonthlyCharges": monthly,
            "TotalCharges": total_charges,
            schema.TARGET: np.where(rng.random(n) < churn_p, "Yes", "No"),
        }
    )

    return frame.astype(str)


@pytest.fixture(scope="session")
def raw_frame() -> pd.DataFrame:
    """Raw-shaped synthetic data, identical on every run."""
    return make_synthetic_raw()


@pytest.fixture(scope="session")
def demo_csv() -> Path:
    """Path to the committed demo CSV, regenerated if it drifts from the generator."""
    FIXTURE_DIR.mkdir(parents=True, exist_ok=True)
    expected = make_synthetic_raw(n=120, seed=7)
    if not DEMO_CSV.exists() or not pd.read_csv(DEMO_CSV, dtype=str).equals(expected):
        expected.to_csv(DEMO_CSV, index=False)
    return DEMO_CSV


@pytest.fixture(scope="session")
def clean_frame(raw_frame: pd.DataFrame) -> pd.DataFrame:
    from churnsense.data.loader import clean_frame as _clean

    return _clean(raw_frame)[0]


@pytest.fixture(scope="session")
def cfg() -> Config:
    return load_config()


@pytest.fixture(scope="session")
def monkeypatch_session():
    """Session-scoped monkeypatch, for module-scoped fixtures that need patching."""
    from _pytest.monkeypatch import MonkeyPatch

    patcher = MonkeyPatch()
    yield patcher
    patcher.undo()


# --- the dashboard, served synthetic data ------------------------------------

#: Stands in for the dataset file's SHA-256 - a real digest, of a fixed string,
#: so it passes the format check. The synthetic model records it, so its
#: partitions are trusted exactly as the real artifact's would be.
SYNTHETIC_SHA256 = hashlib.sha256(b"synthetic customers").hexdigest()


@pytest.fixture(scope="session")
def dashboard_parts(clean_frame: pd.DataFrame, cfg: Config):
    from churnsense.data.loader import features_and_target
    from churnsense.data.split import make_splits

    X, y = features_and_target(clean_frame, cfg)
    return make_splits(X, y, cfg)


@pytest.fixture(scope="session")
def dashboard_predictor(dashboard_parts, cfg: Config, tmp_path_factory):
    """A model trained on synthetic data, recording the data and split it was trained on."""
    from churnsense.models.predict import load_predictor
    from churnsense.models.train import save_artifact, train_all

    parts = dashboard_parts
    outcome = train_all(parts.X_train, parts.y_train, parts.X_val, parts.y_val, cfg=cfg)
    directory = tmp_path_factory.mktemp("dashboard_artifacts")
    save_artifact(
        outcome, directory, cfg, data_sha256=SYNTHETIC_SHA256, split_digest=parts.digest()
    )
    return load_predictor(directory)


@pytest.fixture(scope="session")
def book(clean_frame: pd.DataFrame, dashboard_predictor):
    """What app.data builds from the synthetic customers: ``data.Book``."""
    from app import data

    return data.score_book(clean_frame, SYNTHETIC_SHA256, dashboard_predictor)


@pytest.fixture
def dashboard(monkeypatch, dashboard_predictor, book):
    """Open the real app script on a section, served ``book`` and the synthetic model.

    Nothing real is read: the data layer's book and model are replaced, and so
    are the cached SHAP artifacts. Reading the raw file fails the test, by
    whichever path a section reaches it. Call it with a section name,
    optionally with another ``data.Book``; with no name it runs the landing page.
    """
    import streamlit as st
    from app import data
    from streamlit.testing.v1 import AppTest

    from churnsense.data import loader

    script = str(Path(__file__).resolve().parents[1] / "app" / "streamlit_app.py")

    def no_real_data(*_, **__):
        raise AssertionError("a dashboard test tried to read the real dataset")

    monkeypatch.setattr(data, "_dataset", no_real_data)
    # load_clean hashes the file before reading it.
    monkeypatch.setattr(loader, "verify_dataset", no_real_data)
    monkeypatch.setattr(loader, "read_raw", no_real_data)
    monkeypatch.setattr(data, "predictor", lambda: dashboard_predictor)
    monkeypatch.setattr(data, "shap_importance", lambda: None)
    monkeypatch.setattr(data, "report_json", lambda _name: None)

    def open_section(section: str | None = None, served=None):
        st.cache_data.clear()  # shap_background is cached and depends on the book
        monkeypatch.setattr(data, "_book", lambda: served if served is not None else book)
        at = AppTest.from_file(script, default_timeout=120).run()
        if section is not None:
            at.radio(key="nav").set_value(section).run()
        assert not at.exception, [e.value for e in at.exception]
        return at

    return open_section
